-- INSERT preguntas FIR 2024 (convocatoria FSE 2024, Farmacia)
-- Fuente: Cuaderno_2024_F_0_C.pdf + respuestas_2024.xlsx
-- Generado: 206 preguntas validas de 210 impresas (4 anuladas excluidas: 53, 169, 172, 190)
-- Preguntas 1, 10, 11, 16, 18, 127, 132, 146, 159, 161, 164, 176, 178 dependen visualmente de
-- una estructura/imagen/figura: se cargan con imagen_path apuntando al recorte
-- rescatado del PDF y explicacion_calidad='sin_imagen' (Groq no tiene vision,
-- la explicacion real queda pendiente de un futuro paso con modelo con vision).
-- tema queda NULL: se clasificara en un paso posterior.

BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.preguntas WHERE "año" = 2024) THEN
    RAISE EXCEPTION 'Ya existen preguntas del año 2024 en la tabla preguntas — abortando para evitar duplicados.';
  END IF;
END $$;


COMMIT;

