INSERT INTO public.preguntas
  ("año", numero, pregunta, opcion_a, opcion_b, opcion_c, opcion_d, opcion_e, correcta, imagen_path, tema, explicacion_calidad)
VALUES
  (2024, 1, '¿En cuál de las posiciones marcadas en la molécula de omeprazol tiene lugar la protonación que inicia el proceso de activación de este profármaco?:', 'Posición A.', 'Posición B.', 'Posición C.', 'Posición D.', NULL, 'd', '/imagenes-fir/2024/1.png', NULL, 'sin_imagen'),
  (2024, 2, 'Los fármacos que se absorben por vía oral tienden a cumplir lo que se conoce como reglas de Lipinski. ¿Cuál de los siguientes requisitos NO se ajusta a dichas reglas?:', 'Peso molecular inferior a 500.', 'Logaritmo de P inferior a 5.', 'Número de grupos donadores de enlaces de H inferior a 5.', 'Número de grupos aceptores de enlaces de H inferior a 5.', NULL, 'd', NULL, NULL, NULL),
  (2024, 3, 'El orlistat se utiliza para combatir la obesidad. Actúa inhibiendo la lipasa pancreática y acila uno de los aminoácidos del centro activo. ¿De qué aminoácido se trata?:', 'Serina.', 'Histidina.', 'Ácido aspártico.', 'Lisina.', NULL, 'a', NULL, NULL, NULL),
  (2024, 4, 'Ciertos efectos secundarios de la ciclofosfamida derivan de la acroleína que se forma en el proceso de su activación. ¿Cuál de los siguientes fármacos, administrados conjuntamente con la ciclofosfamida, puede disminuir su toxicidad?:', 'Omeprazol.', 'N-acetilcisteína.', 'Hidrocortisona.', 'Vitamina C.', NULL, 'b', NULL, NULL, NULL),
  (2024, 5, '¿Cuál es el efecto de la sustitución del grupo bencilo de la bencilpenicilina por un grupo atractor de electrones?:', 'Espectro antibacteriano ampliado.', 'Mayor actividad.', 'Mayor estabilidad frente a betalactamasas.', 'Mayor estabilidad frente a los ácidos.', NULL, 'd', NULL, NULL, NULL),
  (2024, 6, 'El captopril es un inhibidor de la enzima conversora de angiotensina, que se diseñó modificando la estructura de la succinilprolina, por introducción de un metilo en la cadena carbonada, y sustitución del grupo CO2H. ¿Qué grupo X hay en su lugar en el captopril?:', 'Un grupo hidroxilo.', 'Un grupo mercapto.', 'Un grupo acetilo.', 'Un grupo amino.', NULL, 'b', NULL, NULL, NULL),
  (2024, 7, '¿Qué nombre reciben los análogos de morfina que carecen del puente oxigenado entre las posiciones 4 y 5?:', 'Benzomorfanos.', 'Morfinanos.', 'Fenilpiperidinas.', 'Oripavinas.', NULL, 'b', NULL, NULL, NULL),
  (2024, 8, '¿Cuál de las siguientes modificaciones resulta útil para disminuir el metabolismo por hidroxilación aromática de fármacos que incluyen algún arilo en su estructura?:', 'Introducir un grupo metoxilo en posición para.', 'Introducir un halógeno en posición para.', 'Introducir un grupo metilo en posición para.', 'El metabolismo de los grupos arilo no se ve afectado por los sustituyentes.', NULL, 'b', NULL, NULL, NULL),
  (2024, 9, '¿Cuál de los siguientes fármacos tricíclicos ejerce su acción principalmente por interacción con receptores muscarínicos?:', 'El compuesto A.', 'El compuesto B.', 'El compuesto C.', 'El compuesto D.', NULL, 'd', NULL, NULL, NULL),
  (2024, 10, '¿Cuál es el papel del fragmento marcado en la estructura del siguiente fármaco?:', 'Mejorar la interacción del grupo guanidina con la diana.', 'Disminuir la duración de acción del fármaco.', 'Aumentar la duración de acción del fármaco.', 'Disminuir la basicidad del grupo guanidina.', NULL, 'd', '/imagenes-fir/2024/10.png', NULL, 'sin_imagen'),
  (2024, 11, '¿Cuál es la finalidad de la modificación marcada en el fármaco B, diseñado por manipulación estructural de A?:', 'Aumentar la lipofilia del fármaco para facilitar su acceso al interior de las células.', 'Dificultar la formación de un catión alílico capaz de alquilar bases del ADN.', 'Mejorar el carácter antagonista del fármaco.', 'Establecer una interacción adicional que refuerza la unión al receptor.', NULL, 'b', '/imagenes-fir/2024/11.png', NULL, 'sin_imagen'),
  (2024, 12, 'Las antraciclinas son agentes antitumorales que poseen en su estructura un fragmento de betahidroxicarbonilo capaz de formar complejos con Fe3+. ¿Por qué estos complejos refuerzan la acción antitumoral de dichos fármacos?:', 'Favorecen reacciones de alquilación de bases del ADN.', 'Favorecen la intercalación entre las bases del ADN.', 'Promueven la formación de radicales hidroxilo.', 'Estimulan la despolimerización de los microtúbulos.', NULL, 'c', NULL, NULL, NULL),
  (2024, 13, 'El peróxido de hidrógeno puede generar en el organismo especies reactivas de oxígeno a través de la reacción de Fenton. Indique cuál de los siguientes compuestos es capaz de prevenir dicha reacción:', 'Ácido ascórbico.', 'Alfa-tocoferol.', 'Dexrazoxano.', 'Alfa-caroteno.', NULL, 'c', NULL, NULL, NULL),
  (2024, 14, 'Teniendo en cuenta la estructura general de los glucocorticoides, y su relación estructura-actividad, ¿cuál de las modificaciones propuestas conduciría a compuestos con mayor actividad antiinflamatoria?:', 'Introducción de un átomo de flúor en la posición 9-alfa.', 'La oxidación del hidroxilo en posición 11.', 'La acetilación del hidroxilo en posición 21.', 'La introducción de un doble enlace entre las posiciones 15 y 16.', NULL, 'a', NULL, NULL, NULL),
  (2024, 15, '¿Cuál de las siguientes reacciones metabólicas de fase II ayuda a eliminar del organismo metabolitos electrófilos?:', 'Conjugación con glutatión.', 'Conjugación con sulfato.', 'Acetilación.', 'Glucuronidación.', NULL, 'a', NULL, NULL, NULL),
  (2024, 16, 'El compuesto cuya estructura se representa a continuación es:', 'Un agente antiviral que actúa incorporándose como falso nucleósido e inhibiendo la ARN-polimerasa.', 'Un agente antifúngico que actúa como inhibidor de la timidilato sintasa.', 'Un agente antineoplásico.', 'Un agente antibacteriano que actúa como inhibidor competitivo reversible de la dihidrofolato reductasa.', NULL, 'c', '/imagenes-fir/2024/16.png', NULL, 'sin_imagen'),
  (2024, 17, '¿Cuál de los reactivos que se indican son adecuados como materiales de partida para la síntesis del norfloxacino?:', 'Un derivado de benzofenona y glicinato de etilo.', 'Un derivado de anilina y un haluro de benzoílo.', 'Un derivado de anilina y etoximetilenmalonato de dietilo.', 'Un derivado de anilina y acroleína.', NULL, 'c', NULL, NULL, NULL),
  (2024, 18, '¿Cuál de los fragmentos marcados en la estructura de este agente antimalárico permite que se acumule en el interior de la vacuola digestiva de Plasmodium?:', 'Los fragmentos c y e.', 'Los fragmentos b y d.', 'Los fragmentos a y b.', 'Los fragmentos a y d.', NULL, 'b', '/imagenes-fir/2024/18.png', NULL, 'sin_imagen'),
  (2024, 19, '¿Cuál es la manifestación clínica que menos esperaría en una infección causada por Fusarium spp.?:', 'Diarrea crónica.', 'Onicomicosis.', 'Queratitis.', 'Fungemia.', NULL, 'a', NULL, NULL, NULL),
  (2024, 20, '¿Qué condiciones de las siguientes son necesarias para que el hongo basidiomiceto Malassezia furfur crezca en un cultivo?:', 'Incubar las placas a 42ºC y en atmósfera microaerofílica.', 'Medios de cultivo habituales cubiertos con aceite de oliva.', 'Incubar las placas a 35ºC y en atmósfera anaerobia.', 'Medios específicos ricos en niacina.', NULL, 'b', NULL, NULL, NULL),
  (2024, 21, 'Nocardia se visualiza en la tinción de Gram en forma de:', 'Diplococos grampositivos.', 'Diplococos gramnegativos.', 'Bacilos grampositivos ramificados.', 'Bacilos gramnegativos.', NULL, 'c', NULL, NULL, NULL),
  (2024, 22, '¿Qué antibiótico se utiliza en el tratamiento de la diarrea causada por Clostridioides difficile toxigénico?:', 'Fidaxomicina.', 'Bezlotoxumab.', 'Clindamicina.', 'Cefotaxima.', NULL, 'a', NULL, NULL, NULL),
  (2024, 23, '¿Qué antibiótico es inactivo frente a Pseudomonas aeruginosa?:', 'Amikacina.', 'Linezolid.', 'Ceftolozano-tazobactam.', 'Ceftazidima-avibactam.', NULL, 'b', NULL, NULL, NULL),
  (2024, 24, '¿Cuál de los siguientes microorganismos presenta test de CAMP positivo?:', 'Streptococcus pyogenes.', 'Streptococcus pneumoniae.', 'Streptococcus mitis.', 'Streptococcus agalactiae.', NULL, 'd', NULL, NULL, NULL),
  (2024, 25, '¿Cuál de las siguientes relaciones entre antibiótico y mecanismo de acción es correcto?:', 'Linezolid – Inhibición de la ADN-girasa.', 'Azitromicina – Unión a la subunidad 50S del ribosoma bacteriano e inhibición de la síntesis de proteínas.', 'Ciprofloxacino – Inhibición de la síntesis de la pared bacteriana.', 'Amikacina – Despolarización de la membrana.', NULL, 'b', NULL, NULL, NULL),
  (2024, 26, '¿Qué mecanismo intrínseco de resistencia a antibióticos beta-lactámicos presenta Serratia?:', 'Carbapenemasa de clase D (OXA).', 'Beta-lactamasa plasmídica de clase A (TEM-1).', 'Beta-lactamasa cromosómica inducible de clase C (AmpC).', 'Mutación de porinas (OprD).', NULL, 'c', NULL, NULL, NULL),
  (2024, 27, '¿Para qué sirve la tinción de Ziehl-Neelsen?:', 'Para teñir micobacterias y otros microorganismos ácido-alcohol resistentes.', 'Para separar los principales grupos de bacterias (grampositivas y gramnegativas).', 'Para detectar parásitos sanguíneos.', 'Para la detección e identificación de protozoos fecales.', NULL, 'a', NULL, NULL, NULL),
  (2024, 28, '¿A cuál de estos microorganismos corresponden las siguientes características: Cocos grampositivos en racimos, colonias beta-hemolíticas, catalasa-positivo, coagulasa-positivo?:', 'Staphylococcus aureus.', 'Listeria monocytogenes.', 'Streptococcus pyogenes.', 'Bacteroides fragilis.', NULL, 'a', NULL, NULL, NULL),
  (2024, 29, '¿Cuál es la característica distintiva de Mycoplasma pneumoniae, en comparación con otras bacterias?:', 'Presencia de cápsula.', 'Ausencia de pared celular.', 'Producción de esporas.', 'Ácido-alcohol resistencia.', NULL, 'b', NULL, NULL, NULL),
  (2024, 30, '¿Qué técnica ha demostrado efectividad en infecciones recurrentes por Clostridioides difficile?:', 'Terapia con probióticos.', 'Trasplante de microbiota fecal.', 'Inmunoterapia.', 'Terapia con bacteriófagos.', NULL, 'b', NULL, NULL, NULL),
  (2024, 31, 'Con respecto a la resistencia a glicopéptidos en los enterococos, señale la opción INCORRECTA:', 'Las cepas con fenotipo VanA muestran resistencia a vancomicina y teicoplanina.', 'Enterococcus gallinarum y Enterococcus casseliflavus presentan resistencia intrínseca de alto nivel a vancomicina.', 'Las cepas con fenotipo VanB muestran resistencia a vancomicina, pero no a teicoplanina.', 'Las cepas con fenotipo VanC muestran resistencia a vancomicina, pero no a teicoplanina.', NULL, 'b', NULL, NULL, NULL),
  (2024, 32, '¿Cuál de los siguientes antimicrobianos sería más activo frente a una infección por Acinetobacter baumannii?:', 'Sulbactam/durlobactam.', 'Ertapenem.', 'Ceftriaxona.', 'Daptomicina.', NULL, 'a', NULL, NULL, NULL),
  (2024, 33, 'En relación a las infecciones producidas por microorganismos grampositivos, ¿cuál de los siguientes síndromes clínicos está mediado por la producción de una toxina?:', 'Empiema.', 'Escarlatina.', 'Endocarditis.', 'Erisipeloide.', NULL, 'b', NULL, NULL, NULL),
  (2024, 34, 'Las cepas multirresistentes de Mycobacterium tuberculosis (MDR-TB) se definen como:', 'Resistentes al menos a isoniacida.', 'Resistentes al menos a isoniacida y rifampicina.', 'Resistentes al menos a isoniacida, rifampicina y pirazinamida.', 'Resistentes al menos a isoniacida, rifampicina, pirazinamida y etambutol.', NULL, 'b', NULL, NULL, NULL),
  (2024, 35, 'Señale la respuesta FALSA sobre Neisseria meningitidis:', 'Se transmite por gotas.', 'Produce infecciones adquiridas en el laboratorio.', 'No crece en agar sangre.', 'Es sensible a cefotaxima.', NULL, 'c', NULL, NULL, NULL),
  (2024, 36, 'Señale la asociación correcta:', 'Bartonella henselae - Fiebre de las trincheras.', 'Brucella abortus - Síndrome de Reiter.', 'Neisseria meningitidis - Síndrome de Waterhouse-Friderichsen.', 'Listeria monocytogenes - carbunco.', NULL, 'c', NULL, NULL, NULL),
  (2024, 37, '¿Qué compuesto actúa como inhibidor de una carbapenemasa tipo VIM (clase B de Ambler)?:', 'Ácido etilenodiaminotetraacético (EDTA).', 'Ácido borónico.', 'Ácido clavulánico.', 'Ácido fusídico.', NULL, 'a', NULL, NULL, NULL),
  (2024, 38, '¿Qué parásito puede ser diagnosticado durante la fase aguda de la enfermedad mediante microscopía directa de sangre periférica en fresco?:', 'Plasmodium falciparum.', 'Leishmania chagasi.', 'Trypanosoma cruzi.', 'Toxoplasma gondii.', NULL, 'c', NULL, NULL, NULL),
  (2024, 39, '¿A qué especie de Plasmodium corresponde la siguiente descripción morfológica: los trofozoítos tienen un citoplasma ameboide, los esquizontes tienen de 12 a 24 merozoítos y los gametocitos son redondos?:', 'P. vivax.', 'P. ovale.', 'P. malariae.', 'P. knowlesi.', NULL, 'a', NULL, NULL, NULL),
  (2024, 40, '¿Qué parásito trematodo causa alteración de los conductos biliares?:', 'Schistosoma mansoni.', 'Opistorchis viverrini.', 'Paragonimus westermani.', 'Schistosoma mekongi.', NULL, 'b', NULL, NULL, NULL),
  (2024, 41, 'El modelo matemático de Heckel proporciona información de utilidad sobre:', 'El tamaño de partícula medio de un material pulverulento para su dosificación en cápsulas rígidas o comprimidos.', 'El grado de sedimentación de partículas sólidas en una determinada formulación en suspensión.', 'La estabilidad de un fármaco en relación con la temperatura y en función de la energía de activación.', 'Las características de plasticidad de una mezcla pulverulenta para su posible dosificación en comprimidos.', NULL, 'd', NULL, NULL, NULL),
  (2024, 42, '¿Cómo se define el concepto de velocidad de disolución aparente?:', 'Velocidad de disolución de una sustancia pura tras su compactación bajo la condición de mantenimiento constante del área superficial.', 'Velocidad de disolución de un sólido pulverulento o un granulado bajo la condición de mantenimiento de las propiedades de densidad aparente.', 'Velocidad de disolución de sustancias puras o en preparaciones en polvo o granulados, en un equipo de flujo continuo.', 'Velocidad de disolución de sustancias puras en equipos de flujo continuo, manteniendo constante el flujo aparente del medio de disolución.', NULL, 'c', NULL, NULL, NULL),
  (2024, 43, 'Indique cuál de los siguientes métodos se corresponde con la fabricación de cápsulas gelatinosas blandas:', 'El método de Scherer o de matrices rotatorias.', 'El método de Schulman o de matrices concéntricas.', 'El método de Higuchi o de inyectores concéntricos.', 'El método de Hopkins o de microfluídica inversa a baja presión.', NULL, 'a', NULL, NULL, NULL),
  (2024, 44, 'Señale mediante qué técnica se determina la osmolalidad o tono osmótico de un preparado inyectable:', 'Osmometría de difracción láser con transformada de Fourier.', 'Determinación del descenso del punto de congelación de la disolución.', 'Determinación potenciométrica de la fuerza iónica de la disolución.', 'Osmometría por incremento del punto de ebullición de la disolución.', NULL, 'b', NULL, NULL, NULL),
  (2024, 45, 'Señale el tipo de empaquetamiento de las partículas esféricas mostrado en el siguiente dibujo:', 'Cúbico.', 'Hexagonal (primitivo).', 'Tetragonal (centrado).', 'Hexagonal (cerrado).', NULL, 'a', NULL, NULL, NULL),
  (2024, 46, 'Entre las características de las microemulsiones en sus aplicaciones farmacéuticas, señale la respuesta FALSA:', 'Permiten solubilizar compuestos químicamente incompatibles en cada fase sin que se produzca interacción entre ellos.', 'Al presentar una viscosidad más alta que las emulsiones se extienden mejor sobre la piel y mucosas.', 'Los glóbulos de fase interna con un elevado contenido en tensoactivos y cotensoactivos facilitan la penetración transdérmica del fármaco.', 'La elevada proporción de tensoactivos que incorporan pueden causar toxicidad.', NULL, 'b', NULL, NULL, NULL),
  (2024, 47, 'Señale el nombre del aparato que se muestra a continuación, empleado para separar las partículas del sólido en fracciones granulométricas:', 'Multicámara de sedimentación centrífuga.', 'Elutriador multietapa.', 'Cámara de sedimentación continua.', 'Cámara de sedimentación multietapa.', NULL, 'b', NULL, NULL, NULL),
  (2024, 48, '¿Cuál de las afirmaciones siguientes caracteriza a la córnea?:', 'Está altamente vascularizada.', 'Forma el límite anterior de la cámara posterior del ojo.', 'Carece de terminaciones nerviosas.', 'Es la porción anterior transparente de la túnica fibrosa.', NULL, 'd', NULL, NULL, NULL),
  (2024, 49, 'Señale la respuesta correcta en relación con la gastrina:', 'Es secretada por el intestino delgado.', 'Mantiene la estructura de la mucosa del intestino grueso.', 'Estimula la secreción de NaCl por las células parietales.', 'Estimula la secreción del pepsinógeno por las células principales.', NULL, 'd', NULL, NULL, NULL),
  (2024, 50, 'Señale la respuesta correcta respecto a los posibles destinos del cuerpo amarillo:', 'En caso de embarazo, el sincitiotrofoblasto de la placenta en desarrollo produce gonadotropina coriónica humana e inhibe la somatomamotropina coriónica humana.', 'La gonadotropina coriónica humana mantiene el cuerpo amarillo del embarazo unos 6 meses, a partir de los cuales la placenta se encarga de la producción de progesterona, estrógeno y relaxina.', 'En ausencia de embarazo está presente la LH y el cuerpo amarillo empieza a atrofiarse.', 'En ausencia de embarazo la carencia de estrógeno y progesterona también estimula la liberación de FSH de la hipófisis, reiniciándose el ciclo menstrual.', NULL, 'd', NULL, NULL, NULL),
  (2024, 51, 'El factor VII de la coagulación es el:', 'Acelerador de la conversión de la protrombina sérica (SPCA).', 'Componente tromboplastínico del plasma (PTC).', 'Factor de Fletcher.', 'Factor antihemofílico C.', NULL, 'a', NULL, NULL, NULL),
  (2024, 52, 'La propagación más lenta del impulso cardíaco se produce en:', 'El músculo auricular.', 'El nodo auriculoventricular.', 'El sistema de Purkinje.', 'El tronco de His.', NULL, 'b', NULL, NULL, NULL),
  (2024, 54, 'En la maduración eritroide, ¿cuál de las siguientes células se encuentra entre el eritroblasto basófilo y el eritroblasto ortocromático?:', 'Reticulocito.', 'Eritrocito.', 'Proeritroblasto.', 'Eritroblasto policromático.', NULL, 'd', NULL, NULL, NULL),
  (2024, 55, '¿Cuál es el promedio aproximado de pérdida de agua en las heces?:', '0-50 mL/día.', '100-200 mL/día.', '200-300 mL/día.', 'Más de 300 mL/día.', NULL, 'b', NULL, NULL, NULL),
  (2024, 56, '¿Cuál es la vía de señalización/activación tras la unión de la hormona leptina a su receptor?:', 'GMPc.', 'JAK2.', 'Proteína G.', 'Adenilato ciclasa-AMPc.', NULL, 'b', NULL, NULL, NULL),
  (2024, 57, '¿Cuál de los siguientes es el responsable de la planificación y programación de los movimientos voluntarios?:', 'El vestibulocerebelo.', 'El espinocerebelo.', 'El cerebrocerebelo.', 'La formación reticular.', NULL, 'c', NULL, NULL, NULL),
  (2024, 58, '¿Cómo se denomina el plexo nervioso situado entre las capas musculares longitudinales y circulares del tubo digestivo?:', 'Plexo hipogástrico.', 'Plexo submucoso o de Meissner.', 'Plexo de Schabadasch o Henle.', 'Plexo de Auerbach.', NULL, 'd', NULL, NULL, NULL),
  (2024, 59, 'Señale la relación INCORRECTA:', 'Troponina I – Actina.', 'Troponina T – Tropomiosina.', 'Troponina C – Calcio.', 'Tropomiosina – Miosina.', NULL, 'd', NULL, NULL, NULL),
  (2024, 60, 'Varón de 40 años acude al servicio de urgencias con síntomas de deterioro cognitivo. El hemograma muestra trombopenia marcada. ¿Qué elementos celulares no deberán pasarse por alto en el estudio del frotis de sangre periférica?:', 'Eritrocitos con una zona central más deprimida respecto a los hematíes normales.', 'Hematíes de aspecto redondeado con varias espículas alargadas distribuidas irregularmente por su superficie.', 'Eritrocitos fragmentados.', 'Hematíes redondeados con espículas cortas distribuidas regularmente por toda la superficie.', NULL, 'c', NULL, NULL, NULL),
  (2024, 61, 'En pacientes con LEC NOS (Leucemia Eosinofílica Crónica no Especificada) la enfermedad sufre una transformación a:', 'Enfermedad de Kimura.', 'Linfoma Hodgkin.', 'Linfoma no Hodgkin.', 'Leucemia aguda.', NULL, 'd', NULL, NULL, NULL),
  (2024, 62, 'Las células de Mott son:', 'Linfocitos con citoplasma hialino y abundantes vellosidades debido a la intensa actividad de su citoesqueleto.', 'Células plasmáticas con inclusiones de naturaleza inmunoglobulínica que ocupan la mayor parte del citoplasma y confieren a la célula un aspecto de mórula.', 'Linfocitos de pequeño tamaño, cromatina madura, condensada con aspecto de caparazón de tortuga y una relación núcleo/citoplasma elevada.', 'Células de tamaño grande similar al del monocito con cromatina madura que presenta surcos similares a las circunvoluciones cerebrales.', NULL, 'b', NULL, NULL, NULL),
  (2024, 63, '¿En cuál de las siguientes patologías es una prueba diagnóstica clave la prueba de Coombs directo?:', 'Anemia hemolítica congénita.', 'Anemia hemolítica de causa no inmune.', 'Anemia no hemolítica.', 'Anemia hemolítica adquirida de origen inmune.', NULL, 'd', NULL, NULL, NULL),
  (2024, 64, 'Durante la revisión de un hemograma nos encontramos ante un volumen plaquetar medio (VPM) elevado y decidimos revisar el frotis al microscopio, confirmándose el hallazgo de macrotrombocitos. ¿Cuál de las siguientes deberá ser la sospecha diagnóstica?:', 'Anemia ferropénica.', 'Linfoma folicular del manto.', 'Mielofibrosis.', 'Trombocitopenia asociada al gen MYH9.', NULL, 'd', NULL, NULL, NULL),
  (2024, 65, '¿Cuál de las siguientes es la causa más habitual del satelitismo plaquetar?:', 'Hemoglobinuria paroxística nocturna.', 'Enfermedades hepáticas.', 'Anticoagulante EDTA.', 'Cuerpos de Pappenheimer.', NULL, 'c', NULL, NULL, NULL),
  (2024, 66, 'Señale la afirmación correcta sobre la atrofia muscular espinal:', 'La forma más frecuente es la atrofia muscular espinal tipo 1, presente al nacimiento o en los primeros años de vida.', 'Es una enfermedad ligada al cromosoma X.', 'Se caracteriza por la presencia de movimientos bruscos y demencia.', 'Recientemente se ha autorizado una terapia génica, axicabtagene ciloleucel, para su tratamiento.', NULL, 'a', NULL, NULL, NULL),
  (2024, 67, '¿En cuál de las siguientes situaciones se esperaría encontrar una bradicardia?:', 'Situación inicial de shock séptico por S. aureus resistente a meticilina.', 'Ingesta de un fármaco que bloquee los canales HCN (canales activados por la hiperpolarización y modulados por nucleótidos cíclicos) alterando la corriente tipo If.', 'Situación de hipertiroidismo clínico, con TSH indetectable y T4 elevada.', 'Paciente varón que presenta una hemoglobina de 7,4 g/dL (rango 13 g/dL - 16 g/dL) secundaria a una hemorragia digestiva.', NULL, 'b', NULL, NULL, NULL),
  (2024, 68, 'Una mujer de 61 años ingresa en el hospital por disnea de mínimos esfuerzos y astenia intensa con un NT-proBNP: 1012 pg/mL (normal < 125 pg/mL). En el ecocardiograma se aprecia una fracción de eyección del ventrículo izquierdo (FEVI) del 30%. Se le diagnostica finalmente de insuficiencia cardíaca congestiva. Cuál de las siguientes afirmaciones sería correcta:', 'Nos encontramos ante un caso de insuficiencia cardiaca con FEVI preservada.', 'Un tratamiento domiciliario de elección para esta patología sería la combinación de bisoprolol con ramipril, linagliptina y espironolactona.', 'El hallazgo de concentraciones muy bajas de NT-proBNP no resulta de utilidad para excluir una causa cardíaca de disnea.', 'Durante el manejo de la insuficiencia cardíaca congestiva aguda suele ser de utilidad la administración de diuréticos de asa.', NULL, 'd', NULL, NULL, NULL),
  (2024, 69, '¿Cuál de las siguientes afirmaciones con respecto a la fluidoterapia es FALSA?:', 'La solución de Ringer lactato es un ejemplo de cristaloide.', 'Las soluciones coloidales, como la albúmina al 20%, se utilizan para aumentar el volumen intravascular sanguíneo.', 'La administración de bicarbonato 1/6 molar es una terapia empleada en pacientes que presentan acidosis metabólica.', 'Las soluciones electrolíticas balanceadas se caracterizan por presentar una cantidad de cloro mayor que el cloruro sódico al 0,9%.', NULL, 'd', NULL, NULL, NULL),
  (2024, 70, 'En cuanto a la anticoncepción, señale la respuesta correcta:', 'Los dispositivos intrauterinos de liberación de levonorgestrel se caracterizan por mantener unos niveles de progestágenos sistémicos muy semejantes a los obtenidos tras su administración oral.', 'Los parches anticonceptivos que combinan un derivado estrogénico y un progestágeno parecen presentar una eficacia menor en mujeres con peso de más de 90 kg.', 'Los implantes anticonceptivos habitualmente liberan un agonista del receptor de GnRH, de forma que al producir una estimulación continua del receptor se produce una desensibilización del mismo.', 'La anticoncepción de emergencia se realiza principalmente mediante el uso de un derivado estrogénico en monoterapia.', NULL, 'b', NULL, NULL, NULL),
  (2024, 71, 'La fibrosis quística es una enfermedad rara que presenta más de 1000 variantes alélicas. Señale cuál de las siguientes afirmaciones es FALSA en relación con esta enfermedad:', 'La mutación más frecuentemente hallada es la F508del del gen regulador de la conductancia transmembrana de fibrosis quística (CFTR), que conserva función parcial del conducto transmembrana, pero su degradación está acelerada por ser reconocido como un plegamiento erróneo.', 'El trasplante pulmonar es una opción terapéutica viable en el caso de insuficiencia pulmonar terminal.', 'Elexacaftor es un fármaco recientemente aprobado para el tratamiento de la fibrosis quística, con el mismo mecanismo de acción que ivacaftor, pero más eficaz, de forma que ha desplazado su uso y es actualmente la primera opción de tratamiento en monoterapia.', 'En los pacientes que la padecen, se ve incrementado el riesgo de infección crónica por P. aeruginosa en relación a la población sana, y se pueden emplear aminoglucósidos inhalados para su tratamiento.', NULL, 'c', NULL, NULL, NULL),
  (2024, 72, 'En relación a la fisiopatología de la enfermedad de Alzheimer:', 'Se relaciona con un procesamiento proteolítico erróneo de la proteína tau.', 'Los agregados de péptido beta amiloide son un hallazgo característico de la enfermedad, pero no alteran la funcionalidad celular.', 'La gamma-secretasa es la responsable de la hiperfosforilación de la proteína precursora de amiloide (APP).', 'La presencia del alelo ε4 del gen de la Apolipoproteína E supone un factor de riesgo importante para el desarrollo de la enfermedad.', NULL, 'd', NULL, NULL, NULL),
  (2024, 73, 'Señale la respuesta correcta sobre la enfermedad renal crónica (ERC):', 'En las primeras fases de la ERC existe una hiperfiltración renal producida por cambios adaptativos a la pérdida de nefronas.', 'En estos pacientes se emplean agentes estimulantes de eritropoyetina para conseguir niveles de hemoglobina basales mayores a los límites superiores establecidos para la población sana.', 'Es típica la disminución de los valores de ácido fólico en estos pacientes debido a su menor activación renal.', 'El factor 23 de crecimiento de fibroblastos (FGF-23) aumenta la reabsorción renal de fosfato, y es un marcador que se encuentra elevado en la insuficiencia renal crónica avanzada.', NULL, 'a', NULL, NULL, NULL),
  (2024, 74, 'Un paciente acude a urgencias con bajo nivel de consciencia y malestar digestivo con estreñimiento asociado. En la analítica, destaca un valor de calcio total de 15 mg/dL (rango normal 8,5 mg/dL - 10,5 mg/dL). ¿Cuál de los siguientes enunciados NO sería cierto en relación al paciente?:', 'Es importante conocer los niveles de albúmina, ya que, si estos fueran muy altos, habría que corregir los niveles de calcio total a la baja para compararlos con los intervalos de referencia.', 'Niveles altos de calcio en sangre se relacionan con intervalos QT cortos en el electrocardiograma.', 'El uso de calcitonina en combinación con bifosfonatos parenterales, fundamentalmente el ácido zoledrónico, se considera una buena opción terapéutica en la mayoría de casos.', 'La causa probable de la hipercalcemia podría ser el uso prolongado de furosemida a dosis altas, fármaco que actualmente empleaba el paciente.', NULL, 'd', NULL, NULL, NULL),
  (2024, 75, 'En la película “La tumba de las luciérnagas”, Setsuko, hermana pequeña de Seita, fallece tras una alimentación escasa. Entre sus síntomas, presentó dermatitis, diarrea y alucinaciones. Señale la enfermedad y deficiencia asociada que pudo haber sufrido Setsuko:', 'Déficit de niacina - pelagra.', 'Déficit de vitamina C - escorbuto.', 'Déficit de ácido fólico - Anemia megaloblástica.', 'Déficit de vitamina B6 - beriberi.', NULL, 'a', NULL, NULL, NULL),
  (2024, 76, 'Dentro de la enfermedad inflamatoria intestinal se pueden diferenciar dos etiologías, la Enfermedad de Crohn y la colitis ulcerosa. Señale la afirmación FALSA respecto a estas entidades:', 'En la enfermedad de Crohn es poco frecuente encontrar afectación exclusivamente colónica.', 'La complicación más frecuente de la colitis ulcerosa causante de ingreso hospitalario es la obstrucción intestinal secundaria a una estenosis.', 'La lactoferrina y la calprotectina fecal son marcadores de seguimiento de la evolución de la enfermedad.', 'La aparición de fístulas perianales es un factor de mal pronóstico de la enfermedad de Crohn.', NULL, 'b', NULL, NULL, NULL),
  (2024, 77, 'Señale cuál de las siguientes afirmaciones es correcta sobre la degeneración macular asociada a la edad (DMAE):', 'La DMAE de tipo exudativo se debe fundamentalmente a la aparición de depósitos extracelulares, denominados drusen o drusas, debajo del epitelio del pigmento retiniano.', 'La susceptibilidad a desarrollar DMAE guarda relación con variantes en el gen para el factor H del complemento, un factor activador de la vía clásica del complemento.', 'La administración intravítrea de fármacos con acción antiangiogénica, como el faricimab, tiene indicación en la DMAE exudativa, pero no en la seca.', 'La mayor pérdida de agudeza visual se produce si se ve afectada la fóvea, una parte de la mácula ocupada exclusivamente por bastones.', NULL, 'c', NULL, NULL, NULL),
  (2024, 78, 'Una mujer de 45 años con una fatiga importante de corta evolución, tras realizarse las pruebas pertinentes, es diagnosticada de colangitis biliar primaria. ¿Cuál de las siguientes características NO esperaría encontrar?:', 'Un aumento de los marcadores de colestasis, como la GGT o la fosfatasa alcalina.', 'Detección de anticuerpos antimitocondriales (AMA) frente al complejo piruvato deshidrogenasa.', 'Prurito importante como manifestación clínica.', 'Una buena respuesta de la enfermedad ante el uso de fármacos inhibidores del transportador SGLT2.', NULL, 'd', NULL, NULL, NULL),
  (2024, 79, 'Hay ciertos medicamentos que es importante suspender con la suficiente antelación antes de una cirugía para evitar eventos adversos durante el procedimiento y el periodo postoperatorio. ¿Cuál de las siguientes asociaciones entre fármaco y motivo de suspensión es INCORRECTA?:', 'Insulina aspart - Riesgo de hipoglucemia debido a que el paciente estará en ayunas.', 'Tirzepatida - Aumento de la velocidad de vaciado gástrico, lo cual es contraproducente en una cirugía.', 'Prasugrel - Aumento del riesgo de sangrado, a pesar de ser un antiagregante y no un anticoagulante.', 'Metformina - Riesgo de acidosis láctica en caso de hipovolemia durante la cirugía.', NULL, 'b', NULL, NULL, NULL),
  (2024, 80, 'Indique la relación correcta fármaco – diana - indicación:', 'Daratumumab - CD38 – Mieloma múltiple.', 'Rituximab - CD20 - Tumor de unión gastroesofágica.', 'Isatuximab - CD38 - Cáncer de pulmón.', 'Obinutuzumab - CD19 - Linfoma Hodgkin.', NULL, 'a', NULL, NULL, NULL),
  (2024, 81, 'Indique la respuesta INCORRECTA respecto al fármaco emtricitabina:', 'Es un análogo nucleosídico de citidina.', 'Se puede utilizar de manera combinada con tenofovir disoproxil fumarato en la profilaxis pre-exposición del VIH.', 'Está contraindicado su uso en el embarazo.', 'Su administración es por vía oral.', NULL, 'c', NULL, NULL, NULL),
  (2024, 82, 'Con respecto a los CAR-T (linfocitos o células T con receptores quiméricos para antígenos), indique la opción INCORRECTA:', 'Tisagenlecleucel presenta expresión de CAR contra CD19.', 'Se puede utilizar tocilizumab para el tratamiento del síndrome de liberación de citoquinas.', 'La presencia de fiebre, cefalea, náuseas y taquicardia entre otros, son algunos de los síntomas del síndrome de liberación de citoquinas.', 'La administración de CAR-T no presenta riesgo de toxicidad neurológica.', NULL, 'd', NULL, NULL, NULL),
  (2024, 83, 'Paciente varón de 75 años diagnosticado hace un año de fibrilación auricular no valvular. El paciente inició tratamiento con acenocumarol, pero no logra controles adecuados de INR (Ratio Normalizado International), el último valor de INR fue 1,4. Indique la opción más correcta a seguir:', 'Suspender tratamiento anticoagulante, ya que dada la edad del paciente el riesgo de sangrado es mayor al beneficio esperado.', 'Suspender acenocumarol e iniciar tratamiento con un anticoagulante de acción directa como apixabán.', 'Administrar varias ampollas de vitamina K hasta control del INR y continuar con acenocumarol.', 'Suspender acenocumarol e iniciar tratamiento con argatrobán.', NULL, 'b', NULL, NULL, NULL),
  (2024, 84, 'Paciente de 67 años, diagnosticado de enfermedad de Crohn en tratamiento con infliximab a dosis estándar desde hace 8 años. Recientemente vuelve a tener síntomas de su enfermedad y en la última analítica destacan niveles de fármaco por debajo del límite terapéutico inferior, así como títulos bajos de anticuerpos antifármaco. ¿Cuál de las siguientes opciones considera más acertada?:', 'Añadir otro fármaco al tratamiento, como por ejemplo vedolizumab, para hacer biterapia.', 'Intensificar el tratamiento con infliximab, bien aumentando la dosis o acortando el intervalo terapéutico.', 'Suspender el tratamiento y esperar tres semividas para reintroducirlo.', 'Suspender infliximab e iniciar el fármaco oral baricitinib.', NULL, 'b', NULL, NULL, NULL),
  (2024, 85, 'Indique la relación INCORRECTA fármaco - enfermedad para la que se usa:', 'Tezepelumab - asma grave.', 'Canakinumab - poliposis nasal.', 'Tralokinumab - dermatitis atópica.', 'Siltuximab - enfermedad de Castleman.', NULL, 'b', NULL, NULL, NULL),
  (2024, 86, '¿Cuál de los siguientes fármacos se considera de elección en el tratamiento de la neuralgia del trigémino?:', 'Capsaicina.', 'Lidocaína.', 'Oxicodona.', 'Carbamazepina.', NULL, 'd', NULL, NULL, NULL),
  (2024, 87, '¿Qué tratamiento aconsejaría prescribir a una paciente de 30 años diagnosticada de artritis reumatoide grave, que ha fracasado al tratamiento con metotrexato y leflunomida y que expresa deseo de quedarse embarazada?:', 'Certolizumab pegol.', 'Atezolizumab.', 'Erlotinib.', 'Natalizumab.', NULL, 'a', NULL, NULL, NULL),
  (2024, 88, '¿Cuál de las siguientes afirmaciones sobre ivabradina es FALSA?:', 'Puede ser útil en adultos que presentan intolerancia o una contraindicación al uso de beta-bloqueantes.', 'Puede provocar taquicardias.', 'Puede provocar fibrilación auricular.', 'Puede provocar trastornos oculares.', NULL, 'b', NULL, NULL, NULL),
  (2024, 89, 'Natalizumab se relaciona con un incremento del riesgo de desarrollar Leucoencefalopatía Multifocal Progresiva. Señale cuál de los siguientes NO es un factor de riesgo para desarrollarla:', 'Tratamiento activo con natalizumab por un periodo superior a 2 años.', 'Tratamiento concomitante con antidepresivos tricíclicos.', 'Presencia de anticuerpos frente al virus JC (John Cunningham).', 'Tratamiento previo con otro fármaco inmunosupresor.', NULL, 'b', NULL, NULL, NULL),
  (2024, 90, 'Paciente de 59 años diagnosticada de asma grave. Está en tratamiento con glucocorticoide inhalado + agonista adrenérgico de acción larga (LABA) + montelukast, pero su enfermedad no está controlada. En sus analíticas se objetivan valores de IgE elevados. ¿Cuál de los siguientes tratamientos se le podría prescribir?:', 'Omalizumab.', 'Rituximab.', 'Ustekinumab.', 'Nivolumab.', NULL, 'a', NULL, NULL, NULL),
  (2024, 91, 'Indique la respuesta correcta respecto al tratamiento de la enfermedad renal crónica (ERC):', 'En el tratamiento de la hipertensión es conveniente asociar dos diuréticos ahorradores de potasio a un diurético de asa.', 'La corrección de la acidosis metabólica con bicarbonato sódico retrasa la progresión de la ERC.', 'Es necesario el ajuste de dosis de insulina degludec aproximadamente a la mitad.', 'El acenocumarol es el fármaco de elección en la tromboembolia nefrótica.', NULL, 'b', NULL, NULL, NULL),
  (2024, 92, 'Niña prematura de 28 semanas de gestación con 980 g, que desde los primeros días de vida desarrolla apnea del prematuro, con interrupción de la respiración durante un mínimo de 20 segundos acompañado de cianosis y bradicardia (<80 lpm), sin otra patología subyacente grave. Señale la respuesta correcta sobre el tratamiento farmacológico de elección:', 'Betametasona.', 'Óxido nítrico.', 'Surfactante pulmonar.', 'Cafeína.', NULL, 'd', NULL, NULL, NULL),
  (2024, 93, '¿Qué efecto adverso está asociado a los fármacos habitualmente utilizados en las exacerbaciones de la enfermedad obstructiva crónica (EPOC)?:', 'Sequedad de boca asociada a los inhibidores de la fosfodiesterasa, como roflumilast.', 'Diarrea, náuseas y dolores de cabeza asociados a los antagonistas colinérgicos muscarínicos.', 'Hiperpotasemia asociada a los agonistas β2.', 'Candidiasis orofaríngea asociada al uso de los corticoides inhalados.', NULL, 'd', NULL, NULL, NULL),
  (2024, 94, 'Indique cuál de los siguientes fármacos es un antagonista selectivo del receptor de la endotelina tipo A:', 'Sildenafilo.', 'Bosentan.', 'Macitentan.', 'Ambrisentan.', NULL, 'd', NULL, NULL, NULL),
  (2024, 95, 'Indique la respuesta FALSA sobre los fármacos inhibidores de la PCSK9 (proproteína convertasa subtilisina/kexina tipo 9):', 'Alirocumab está indicado para la hipercolesterolemia primaria (familiar heterocigótica y no familiar), dislipidemia mixta, y enfermedad cardiovascular aterosclerótica establecida.', 'Evolocumab está indicado para la hipercolesterolemia primaria (familiar heterocigótica y no familiar), dislipidemia mixta, hipercolesterolemia familiar homocigótica, y enfermedad cardiovascular aterosclerótica establecida.', 'Alirocumab y evolocumab son anticuerpos monoclonales que se administran vía subcutánea.', 'Entre las reacciones adversas más frecuentes de alirocumab y evolocumab se encuentra el aumento de las enzimas hepáticas AST y ALT.', NULL, 'd', NULL, NULL, NULL),
  (2024, 96, 'Indique la respuesta INCORRECTA sobre el tratamiento de la Enfermedad de Parkinson (EP):', 'La levodopa sigue siendo el tratamiento sintomático más eficaz en la EP.', 'La levodopa presenta un elevado metabolismo periférico por lo que se administra junto a un inhibidor de la LAAD (L-aminoácido aromático-descarboxilasa) que aumenta la biodisponibilidad.', 'Si se presentan náuseas y vómitos en un paciente tratado con levodopa, el antiemético más recomendado es la metoclopramida.', 'Levodopa/carbidopa/entacapona gel intestinal está indicado en la EP avanzada con fluctuaciones motoras graves e hipercinesia o discinesia cuando las combinaciones de medicamentos orales disponibles no han proporcionado resultados satisfactorios.', NULL, 'c', NULL, NULL, NULL),
  (2024, 97, 'Con respecto a tacrolimus indique la respuesta correcta:', 'Es un inhibidor de mTOR (diana de rapamicina en células de mamífero).', 'Debido a la variabilidad farmacocinética entre sujetos, es necesaria una posología individualizada para lograr el tratamiento óptimo.', 'Favorece la activación del linfocito T al inhibir a la calcineurina.', 'Se utiliza como profilaxis del rechazo del trasplante en receptores de aloinjertos hepáticos, pero se encuentra contraindicado su uso en los renales y cardiacos.', NULL, 'b', NULL, NULL, NULL),
  (2024, 98, 'Durante el embarazo se producen modificaciones fisiológicas que pueden influir en la respuesta a los fármacos, debido a que:', 'Aumenta la velocidad del vaciamiento gástrico.', 'Disminuye progresivamente el volumen de agua corporal y, por tanto, el volumen de distribución.', 'Hay una disminución de proteínas plasmáticas, principalmente de la albúmina.', 'Hay una disminución de la filtración glomerular y, por tanto, de la eliminación por esta vía.', NULL, 'c', NULL, NULL, NULL),
  (2024, 99, '¿Cuál es el mecanismo de acción principal de los aminoglucósidos en el tratamiento de infecciones bacterianas?:', 'Inhibición de la síntesis proteica al unirse a la subunidad ribosómica 30S.', 'Inhibición de la síntesis de peptidoglicano en la pared celular bacteriana.', 'Inhibición de la replicación del ADN bacteriano al interferir con la topoisomerasa II.', 'Disrupción de la membrana celular bacteriana mediante la inserción de poros.', NULL, 'a', NULL, NULL, NULL),
  (2024, 100, '¿Qué efecto farmacológico tiene el metimazol?:', 'Inhibición de la conversión periférica de T4 en T3, reduciendo la actividad biológica de las hormonas tiroideas.', 'Estimulación de la liberación de hormonas tiroideas almacenadas en la glándula, aumentando los niveles de T3 y T4 en sangre.', 'Bloqueo de la captación de yodo en las células foliculares, impidiendo la formación de hormonas tiroideas.', 'Inhibición de la peroxidasa tiroidea, lo que reduce la síntesis de hormonas tiroideas T3 y T4.', NULL, 'd', NULL, NULL, NULL),
  (2024, 101, '¿En cuál de los siguientes órganos efectores los impulsos colinérgicos producen un efecto de relajación?:', 'Músculo traqueobronquial.', 'Músculo detrusor de la vejiga urinaria.', 'Vesícula biliar.', 'Esfínteres intestinales.', NULL, 'd', NULL, NULL, NULL),
  (2024, 102, '¿Cuál de los siguientes principios activos antiepilépticos estimula receptores serotoninérgicos?:', 'Fenfluramina.', 'Cannabidiol.', 'Cenobamato.', 'Zonisamida.', NULL, 'a', NULL, NULL, NULL),
  (2024, 103, '¿Cuál de los siguientes principios activos actúa como inhibidor selectivo de la miosina cardiaca?:', 'Mavacamten.', 'Bisoprolol.', 'Verapamilo.', 'Disopiramida.', NULL, 'a', NULL, NULL, NULL),
  (2024, 104, 'Respecto al litio, señale la afirmación verdadera:', 'Uno de sus efectos adversos destacados es su capacidad de producir agranulocitosis.', 'Actúa como agonista de los receptores dopaminérgicos D2.', 'Bloquea la cascada de señalización de fosfatidilinositol en el cerebro.', 'Es un fármaco con un amplio margen terapéutico.', NULL, 'c', NULL, NULL, NULL),
  (2024, 105, 'Si un fármaco A inhibe el metabolismo de otro fármaco B, teniendo en cuenta que B no rinde metabolitos farmacológicamente activos, puede observarse:', 'Una disminución en el efecto de B.', 'Una pérdida en la eficacia farmacológica de B.', 'Una disminución en el tiempo de efecto de B.', 'Un aumento del efecto del fármaco B y en ocasiones de su toxicidad.', NULL, 'd', NULL, NULL, NULL),
  (2024, 106, 'Las reacciones adversas a fármacos de tipo B, tienen como característica:', 'Estar relacionadas con las acciones farmacológicas del mismo.', 'Ser predecibles.', 'Ser impredecibles y no estar relacionadas con las propiedades farmacológicas del mismo.', 'Tener una probabilidad de aparición muy alta en la población.', NULL, 'c', NULL, NULL, NULL),
  (2024, 107, '¿Cuál de las siguientes características de los fármacos da lugar a una mayor excreción biliar?:', 'Sustancias con alto peso molecular.', 'Sustancias con grupos no polares.', 'Compuestos ionizables.', 'Sustancias con bajo peso molecular.', NULL, 'a', NULL, NULL, NULL),
  (2024, 108, '¿Cuál es la razón principal para el uso de un opioide agonista parcial en lugar de un agonista completo en el manejo del dolor?:', 'Mayor duración de acción, lo que permite un alivio del dolor más prolongado.', 'Mayor potencia analgésica, ya que los agonistas parciales activan todos los receptores opioides con alta eficacia.', 'Menor riesgo de desarrollar tolerancia, debido a la menor afinidad por los receptores opioides.', 'Menor riesgo de depresión respiratoria, ya que no provocan una inhibición completa del centro respiratorio.', NULL, 'd', NULL, NULL, NULL),
  (2024, 109, 'En relación con Podophylum peltatum L., indique la respuesta correcta:', 'Se utiliza un extracto de la hoja.', 'Su principio activo, la podofilotoxina, es de naturaleza alcaloídica.', 'La acción antimitótica de su principio activo se debe a que inhibe la polimerización de la tubulina.', 'Pertenece a la familia Araliaceae.', NULL, 'c', NULL, NULL, NULL),
  (2024, 110, 'La raíz de valeriana posee una acción sedante e inductora del sueño debido a un mecanismo de incremento de transmisión gabaérgica, atribuida a la presencia de:', 'Sesquiterpenos no volátiles.', 'Ácidos cinámicos y benzoicos.', 'Alcaloides indólicos.', 'Antraquinonas hidroxiladas.', NULL, 'a', NULL, NULL, NULL),
  (2024, 111, 'Si hablamos de un alcaloide derivado del yohimbano, de tipo indólico, con propiedades antihipertensivas y que carece de propiedades lipolíticas, nos referimos a:', 'Coniína.', 'Reserpina.', 'Nicergolina.', 'Arecolina.', NULL, 'b', NULL, NULL, NULL),
  (2024, 112, 'En un paciente al que se tenga que administrar de forma sistémica un fármaco irritante, como el cisplatino, ¿qué tipo de catéter elegiría?:', 'Un catéter cuya punta se encontrase en la aurícula derecha.', 'Un catéter cuya punta se encontrase en la vena cefálica.', 'Un catéter cuya punta se encontrase en la vena radial.', 'Un catéter cuya punta se encontrase en la arteria femoral.', NULL, 'a', NULL, NULL, NULL),
  (2024, 113, 'Un paciente está en tratamiento con meropenem a dosis máxima para tratar una sepsis por bacterias gramnegativas, ¿cuál de las siguientes estrategias podría proponer para intentar mejorar la eficacia del tratamiento?:', 'Doblar la dosis del fármaco para conseguir un pico de concentración más alto, recomendado en pacientes críticos.', 'Añadir al meropenem un inhibidor de citocromos como el ritonavir, para incrementar los niveles plasmáticos de meropenem sin incrementar la dosis.', 'Administrar el meropenem por vía intramuscular, para conseguir un efecto más sostenido en el tiempo.', 'Incrementar el tiempo en el que meropenem se administra, como por ejemplo realizar una perfusión extendida de 3 horas.', NULL, 'd', NULL, NULL, NULL),
  (2024, 114, 'Acude a urgencias un paciente con taquicardia con QRS ancho, hipotensión y sintomatología anticolinérgica. Recientemente ha aumentado la dosis de clomipramina, si bien sigue en rango de dosis de ficha técnica. Contactan con usted para solicitar una prueba genética del paciente, y evaluar así una posible toxicidad del fármaco. ¿Qué prueba recomendaría?:', 'Genotipar el gen de la glicoproteína P, para detectar una posible infraexpresión de la misma.', 'Genotipar el gen UGT1A1, para detectar una posible actividad baja del mismo.', 'Genotipar el citocromo CYP3A5, para detectar una posible actividad disminuida del mismo.', 'Genotipar el citocromo CYP2C19, para detectar una posible expresión alterada del mismo.', NULL, 'd', NULL, NULL, NULL),
  (2024, 115, 'Un paciente diagnosticado de intestino corto secundario a una resección tumoral se encuentra en tratamiento con clomipramina, pero no está respondiendo adecuadamente. La clomipramina, fármaco clase I según el sistema de clasificación biofarmacéutica (BCS), está formulada como grageas, destacando entre sus excipientes sacarosa, lactosa, gelatina, glicerol y celulosa microcristalina. ¿Cuál de las siguientes acciones recomendaría a su médico para intentar mejorar la respuesta?:', 'Intentar emplear una formulación en forma de cápsula de liberación modificada.', 'Ofrecer un equivalente terapéutico de clase III según la BCS.', 'Machacar la gragea y disolverla en agua.', 'Buscar una alternativa que presente una Tmax>2 horas.', NULL, 'c', NULL, NULL, NULL),
  (2024, 116, 'Para el correcto desarrollo de sistemas de liberación modificada por vía oral se debe considerar la semivida biológica intrínseca del principio activo. ¿Cuál de las siguientes vidas medias consideraría más adecuada para el desarrollo de un sistema de liberación modificada?:', 'Menor de 10 minutos.', 'Entre 6 y 8 horas.', 'Entre 14 y 18 horas.', 'Entre 20 y 24 horas.', NULL, 'b', NULL, NULL, NULL),
  (2024, 117, 'En la administración de fármacos por vía pulmonar, ¿cuál de estas afirmaciones de los inhaladores de polvo seco (DPI) o inhaladores a presión con válvula dosificadora (pMDI) es verdadera?:', 'Los DPI requieren una mayor coordinación en su uso correcto por parte de los pacientes que los pMDI.', 'Los DPI suelen contener excipientes sólidos, como la lactosa.', 'En los pMDI actuales se han eliminado los gases halogenados como propelentes debido a que dañan la capa de ozono.', 'En los DPI la dosis respirable suministrada es dependiente del flujo inspiratorio, aumentando cuando se acopla una cámara espaciadora.', NULL, 'b', NULL, NULL, NULL),
  (2024, 118, 'Respecto a la monitorización farmacocinética de fármacos, ¿cuál de las siguientes asociaciones farmacocinética - farmacodinamia es FALSA?:', 'Concentraciones mínimas de vancomicina superiores a 20 mg/L y riesgo de nefrotoxicidad.', 'Concentraciones máximas de gentamicina superiores a 15 mg/L y riesgo de ototoxicidad.', 'Concentraciones mínimas de infliximab indetectables y riesgo de aparición de anticuerpos anti-infliximab.', 'Concentraciones de digoxina superiores a 2 ng/mL y riesgo de bradicardia.', NULL, 'b', NULL, NULL, NULL),
  (2024, 119, '¿Cómo afecta un aumento en la semivida de eliminación a la concentración en estado estacionario y al tiempo para alcanzarlo en una perfusión intravenosa continua?:', 'Un descenso en la concentración de equilibrio alcanzada y en el tiempo necesario para alcanzar el equilibrio.', 'Un descenso en la concentración de equilibrio alcanzada y un incremento en el tiempo necesario para alcanzar el equilibrio.', 'Un incremento en la concentración de equilibrio alcanzada y en el tiempo necesario para alcanzar el equilibrio.', 'Un incremento en la concentración de equilibrio alcanzada y un descenso en el tiempo necesario para alcanzar el equilibrio.', NULL, 'c', NULL, NULL, NULL),
  (2024, 120, '¿Cuál de las siguientes definiciones corresponde al tiempo medio de residencia (MRT) empleado en el cálculo de parámetros farmacocinéticos mediante métodos modelo-independiente?:', 'Tiempo al cual se absorbe el 60% de una dosis oral de un fármaco.', 'Tiempo al cual se elimina del organismo el 62,3% de una dosis endovenosa de un fármaco.', 'Tiempo al cual se elimina del organismo el 63,2% de una dosis endovenosa de un fármaco.', 'Tiempo al cual se absorbe el 62,3% de una dosis oral de un fármaco.', NULL, 'c', NULL, NULL, NULL),
  (2024, 121, 'Un paciente recibe un bolo intravenoso de 200 mg de un fármaco que presenta una velocidad de eliminación de 10 mg/h y un volumen de distribución de 10 L. ¿Cuál será la concentración de fármaco en el organismo tras 7 h desde su administración?:', '13 mg/L.', '10 mg/L.', '7 mg/L.', 'Se habrá eliminado todo el fármaco.', NULL, 'a', NULL, NULL, NULL),
  (2024, 122, 'Para un fármaco que presenta baja capacidad de extracción hepática, ¿cuál de las siguientes afirmaciones es correcta?:', 'El aclaramiento es dependiente de los cambios de flujo y de la actividad enzimática e independiente de los cambios en la unión a proteínas.', 'El aclaramiento es independiente de cambios en la unión a proteínas.', 'El aclaramiento es independiente de los cambios de flujo y dependiente de los cambios en la unión a proteínas plasmáticas.', 'El aclaramiento es independiente de cambios en la actividad enzimática.', NULL, 'c', NULL, NULL, NULL),
  (2024, 123, 'El etanol es una molécula con un metabolismo complejo, que influye en las rutas catabólicas y anabólicas de otras sustancias. ¿Qué cabría esperar en su metabolismo?:', 'Un aumento de FADH2, producido mediante la metabolización del etanol por la alcohol deshidrogenasa y la aldehído deshidrogenasa.', 'Una disminución del pH de la sangre, ya que favorece, entre otros, el aumento del cociente [lactato/piruvato].', 'Un aumento inmediato de la glucemia, al favorecer la gluconeogénesis e inhibir la glucólisis, para recuperar nucleótidos que se puedan reducir.', 'Una degradación de los ácidos grasos en el hígado, al aumentar el metabolismo de los triglicéridos en detrimento del meta-', NULL, 'b', NULL, NULL, NULL),
  (2024, 124, 'Señale cuál de las siguientes afirmaciones sobre la hemocromatosis es correcta:', 'Puede darse un cuadro similar en la porfiria cutánea tardía.', 'Fármacos como el deferasirox pueden agravar esta patología.', 'Está involucrado el gen EGFR.', 'Las flebotomías fueron durante muchos años el tratamiento de elección, pero actualmente su uso está contraindicado.', NULL, 'a', NULL, NULL, NULL),
  (2024, 125, 'El glucógeno es la principal forma de almacenamiento de glúcidos en los animales. ¿Cuál de las siguientes características lo representa?:', 'Permite movilizar rápidamente muchas unidades de glucosa al presentar múltiples extremos reductores.', 'Tiene una estructura más semejante a la amilopectina del almidón que a la amilosa.', 'Al estar formado por múltiples unidades de glucosa, la osmolaridad que presenta el glucógeno es mucho mayor que la que presentarían estas moléculas de glucosa si se almacenasen de forma individual.', 'Es típico de este polisacárido que se encuentre aminado en sus extremos.', NULL, 'b', NULL, NULL, NULL),
  (2024, 126, 'Un paciente presenta intolerancia hereditaria a la fructosa, y requiere de la administración de inmunoglobulinas para tratar una trombocitopenia inmune primaria. ¿Cuál de los siguientes excipientes debería evitar?:', 'Sorbitol.', 'Albúmina.', 'Prolina.', 'Glicina.', NULL, 'a', NULL, NULL, NULL),
  (2024, 127, '¿Qué molécula de 20 átomos de carbono representa la siguiente estructura?:', 'Una prostaglandina.', 'Una prostaciclina.', 'Una lipoxina.', 'Un leucotrieno.', NULL, 'd', '/imagenes-fir/2024/127.png', NULL, 'sin_imagen'),
  (2024, 128, '¿Cuál de las siguientes situaciones NO favorece la activación de la lipasa sensible a hormonas de los adipocitos?:', 'Desfosforilación de la enzima.', 'Administración de corticoides exógenos.', 'Aumento del AMP cíclico dentro del adipocito.', 'Disminución de los niveles de insulina.', NULL, 'a', NULL, NULL, NULL),
  (2024, 129, '¿Qué es la termogenina, y cuál es su papel fisiológico?:', 'Una lipoproteína que permite la generación de calor en las células musculares.', 'Una proteína endógena desacopladora de la cadena respiratoria, presente en el tejido adiposo pardo.', 'Un neurotransmisor hipotalámico con un papel trascendental en el centro termorregulador del hipotálamo.', 'Una molécula soluble reguladora de la lipogénesis y, con ella, reguladora de la producción de calor corporal.', NULL, 'b', NULL, NULL, NULL),
  (2024, 130, '¿Para cuál de las siguientes enfermedades esperaría que fuese de utilidad la administración de esfingomielinasa ácida recombinante?:', 'Enfermedad de Niemann-Pick.', 'Enfermedad de Hurler.', 'Enfermedad de Brody.', 'Enfermedad de Fanconi-Bickel.', NULL, 'a', NULL, NULL, NULL),
  (2024, 131, 'A una solución del aminoácido glicina que se encuentra a un determinado pH se le aplica un campo eléctrico. Se observa que las moléculas de glicina se desplazan predominantemente hacia el cátodo. Sabiendo que su punto isoeléctrico es de 5,97, ¿cuál de las siguientes afirmaciones sería correcta?:', 'El pH de la solución es inferior al punto isoeléctrico, predominando la forma desprotonada del aminoácido.', 'El pH de la solución es inferior al punto isoeléctrico, predominando la forma protonada del aminoácido.', 'El pH de la solución es superior al punto isoeléctrico, predominando la forma protonada del aminoácido.', 'El pH de la solución es superior al punto isoeléctrico, predominando la forma desprotonada del aminoácido.', NULL, 'b', NULL, NULL, NULL),
  (2024, 132, 'El lutecio (177Lu) oxodotreotida es un radiofármaco indicado en ciertos tipos de tumores neuroendocrinos. Se debe administrar de forma concomitante una solución de aminoácidos para reducir la reabsorción del radiofármaco en los túbulos contorneados proximales. Sabiendo que esta menor reducción en la reabsorción se debe en parte a que los aminoácidos neutralizan la carga eléctrica derivada del ligando unido al 177Lu (imagen en la parte inferior), ¿qué aminoácidos seleccionaría para la administración? NOTA: Asuma que el 177Lu no aporta carga eléctrica debido a que se encuentra formando un complejo de quelación:', 'L-Lisina y L-Arginina.', 'L-Aspartato y L-Glutamato.', 'L-Isoleucina y L-Triptófano.', 'L-Aspartato y L-Arginina.', NULL, 'a', '/imagenes-fir/2024/132.png', NULL, 'sin_imagen'),
  (2024, 133, 'En relación con la proteína que une directamente la polimerasa de ARN tipo I al ADN, ¿qué característica es común en las ARN polimerasas de procariotas, pero no en las de eucariotas?:', 'La existencia de múltiples factores de transcripción específicos para iniciar la transcripción.', 'La necesidad de un solo factor sigma para reconocer el promotor y comenzar la transcripción.', 'La formación de complejos de preiniciación en los promotores de los genes.', 'La capacidad de transcribir genes que contienen intrones y exones.', NULL, 'b', NULL, NULL, NULL),
  (2024, 134, 'El proceso de reparación del ADN por escisión o supresión de una base se inicia por la acción de la enzima:', 'ADN topoisomerasa.', 'ADN primasa.', 'ADN glucosilasa.', 'Proteínas SSB.', NULL, 'c', NULL, NULL, NULL),
  (2024, 135, '¿Cuál de las siguientes secuencias de eventos en el proceso de traducción es la correcta?:', 'El ribosoma se une al ARN mensajero (mARN), el anticodón del ARN de transferencia (tARN) se empareja con el codón del mARN, y se agrega un aminoácido a la cadena polipeptídica.', 'El ribosoma se une al tARN, el codón del tARN se empareja con el anticodón del mARN, y se agrega un aminoácido a la cadena polipeptídica.', 'El ribosoma se une al ADN, el codón del tARN se empareja con el anticodón del mARN, y se agrega un nucleótido a la cadena de mARN.', 'El ribosoma se une al mARN, el anticodón del tARN se empareja con el codón del ADN, y se agrega un nucleótido a la cadena de ADN.', NULL, 'a', NULL, NULL, NULL),
  (2024, 136, 'Durante el proceso de replicación del ADN, se requiere una enzima que sintetice un cebador de ARN para que la ADN polimerasa pueda iniciar la adición de nucleótidos. ¿Cuál es la enzima responsable de este paso crucial?:', 'ADN helicasa.', 'ADN ligasa.', 'Primasa.', 'Exonucleasa.', NULL, 'c', NULL, NULL, NULL),
  (2024, 137, '¿Cuál es la principal diferencia funcional entre la heterocromatina y la eucromatina en el contexto de la expresión génica?:', 'La eucromatina está asociada con regiones del ADN que son transcripcionalmente activas, mientras que la heterocromatina está asociada con regiones que son transcripcionalmente inactivas.', 'Los genes que contiene la eucromatina no se expresan, mientras que los que contiene la heterocromatina sí lo hacen.', 'La heterocromatina permite la transcripción activa de genes, mientras que la eucromatina silencia los genes.', 'No existe ninguna diferencia funcional entre la heterocromatina y la eucromatina.', NULL, 'a', NULL, NULL, NULL),
  (2024, 138, 'Durante la replicación del ADN, la ADN ligasa tiene un papel crucial. ¿Cuál de las siguientes opciones describe mejor su función específica en este proceso?:', 'La ADN ligasa añade nucleótidos a la cadena en crecimiento durante la replicación.', 'La ADN ligasa es responsable de unir los fragmentos de Okazaki en la cadena rezagada para formar una cadena continua.', 'La ADN ligasa desenrolla la doble hélice de ADN para facilitar la replicación.', 'La ADN ligasa sintetiza los cebadores de ARN necesarios para iniciar la síntesis de ADN.', NULL, 'b', NULL, NULL, NULL),
  (2024, 139, '¿Cuál de las siguientes afirmaciones es correcta sobre el proceso de introducción de ADN exógeno en las células huésped?:', 'El proceso de introducir ADN exógeno en células procariotas se denomina transfección, mientras que en células eucariotas se denomina transformación.', 'La introducción de ADN exógeno en células eucariotas o procariotas no necesita vectores.', 'Sólo puede realizarse utilizando cósmidos.', 'Para que el ADN plasmídico se replique autónomamente dentro de la célula huésped, es necesario que el vector contenga un origen de replicación.', NULL, 'd', NULL, NULL, NULL),
  (2024, 140, '¿Cuál de las siguientes modificaciones postraduccionales es responsable de estabilizar la estructura terciaria de las proteínas mediante la formación de enlaces covalentes entre residuos de cisteína?:', 'Metilación.', 'Fosforilación.', 'Glucosilación.', 'Puentes disulfuro.', NULL, 'd', NULL, NULL, NULL),
  (2024, 141, 'En relación con los telómeros, ¿qué respuesta es cierta?:', 'Están formados por secuencias repetitivas de ADN no codificante que acortan el tamaño en cada replicación celular.', 'Son estructuras que codifican directamente para proteínas esenciales.', 'Son el lugar donde los cromosomas se mantienen unidos durante la división celular, de manera que no pierdan sus cromátidas hermanas.', 'Son regiones que acortan su longitud con cada división celular por la acción de la enzima telomerasa.', NULL, 'a', NULL, NULL, NULL),
  (2024, 142, 'El metanol y el etilenglicol son dos moléculas que causan importantes daños tras su ingesta debido a su conversión en metabolitos tóxicos. Escoja la respuesta correcta:', 'Ambos alcoholes acaban metabolizándose en oxalato, el cual daña el nervio óptico y provoca ceguera en estas intoxicaciones.', 'Su tratamiento, basado en el empleo de fomepizol, consiste en la inhibición del CYP3A4.', 'Tras la ingesta de estos compuestos, cabe esperarse un gap osmolar inicialmente elevado, antes de que los alcoholes se metabolicen.', 'Intoxicaciones con ambos alcoholes tienden a producir alcalosis metabólicas importantes, que disminuyen la frecuencia respiratoria.', NULL, 'c', NULL, NULL, NULL),
  (2024, 143, 'AC es una paciente de 65 años con diabetes mellitus tipo 2 a la que recientemente se le ha diagnosticado una anemia hemolítica autoinmune. Requiere de transfusiones constantes y muy posiblemente comience con corticoides de manera continuada. ¿Cuál sería el parámetro más indicado para hacer seguimiento de su diabetes tipo 2?:', 'Fructosamina.', 'Hemoglobina glicosilada (HbA1c).', 'Presencia de cetonas en la orina.', 'Cetonemia en ayunas y capilar.', NULL, 'a', NULL, NULL, NULL),
  (2024, 144, 'Señala la afirmación FALSA respecto a la hemofilia:', 'La desmopresina es un análogo sintético de la vasopresina que provoca un aumento transitorio en los niveles del Factor IX y del Factor de Von Willebrand, mediante su liberación desde depósitos en las células endoteliales vasculares.', 'La hemofilia A es una deficiencia de factor VIII, la hemofilia B es una deficiencia del factor IX y la hemofilia C es una deficiencia del factor XI.', 'La hemartrosis espontánea es un problema característico en la hemofilia y puede conducir a una artritis deformante.', 'El emicizumab es un anticuerpo biespecífico asimétrico con una región de cadena variable de inmunoglobulina que se une al FIXa y otra que se une al FX. Es eficaz en pacientes con hemofilia A grave con o sin inhibidores.', NULL, 'a', NULL, NULL, NULL),
  (2024, 145, '¿Cuál de los siguientes paneles de pruebas en sangre periférica consideraría el más adecuado para el seguimiento de la eficacia y la seguridad de pacientes con cáncer de mama luminal A metastásico en tratamiento con palbociclib?:', 'Neutrófilos en sangre periférica, NT-proBNP, troponina T, CA 19-9, CEA.', 'Neutrófilos en sangre periférica, CA 15-3, CA 27.29.', 'Neutrófilos en sangre periférica, PDL-1, HER-2.', 'Neutrófilos en sangre periférica, hemoglobina glicosilada, CA 125.', NULL, 'b', NULL, NULL, NULL),
  (2024, 146, 'El gen LEP (leptina) presenta un polimorfismo G2478A de interés clínico. La enzima de restricción HhaI reconoce la secuencia GCG^C y se ha utilizado en el genotipado por PCR-RFLP (Polimorfismo en la Longitud de los Fragmentos de Restricción) de la imagen. ¿En qué calles estará presente el alelo G?:', 'Solamente en la calle 2.', 'En las calles 3 y 4.', 'En las calles 1 y 3.', 'Solamente en la calle 4.', NULL, 'b', '/imagenes-fir/2024/146.png', NULL, 'sin_imagen'),
  (2024, 147, 'Respecto al análisis del líquido cefalorraquídeo en patologías neurológicas, seleccione la combinación de marcadores más útil para el diagnóstico diferencial entre enfermedad de Creutzfeldt-Jakob y esclerosis múltiple:', 'Índice de IgG Delpech-Tibbling y proteína tau fosforilada.', 'α-sinucleína y proteína 14-3-3.', 'Proteína 14-3-3 y bandas oligoclonales de IgG.', 'Adenosina desaminasa y α-sinucleína.', NULL, 'c', NULL, NULL, NULL),
  (2024, 148, 'Un paciente es ingresado por una obstrucción intestinal. El paciente lleva 5 días en ayunas, y se le acaba de prescribir una nutrición parenteral total al 100% de los requerimientos calóricos. Al día siguiente, el paciente presenta edema periférico e insuficiencia respiratoria, siendo diagnosticado de un posible síndrome de realimentación. ¿Qué parámetro analítico es más probable encontrar alterado en esta situación?:', 'Sodio disminuido.', 'Cloro disminuido.', 'Fosfato disminuido.', 'Calcio disminuido.', NULL, 'c', NULL, NULL, NULL),
  (2024, 149, 'Seleccione la afirmación correcta en relación a la transferrina:', 'Sus niveles séricos habitualmente se encuentran por debajo del rango normal en la anemia ferropénica.', 'El índice de saturación de la transferrina estará aumentado en la anemia de las enfermedades crónicas.', 'Es una proteína que en el proteinograma se encuentra en la banda de las αglobulinas.', 'En la hemocromatosis la concentración', NULL, 'd', NULL, NULL, NULL),
  (2024, 150, 'De los siguientes resultados de bilirrubina (Bil) y urobilinógeno (Uro) en el urianálisis, ¿qué combinación sugiere una ictericia prehepática?:', 'Bil y Uro negativos.', 'Bil positiva y Uro negativo.', 'Bil y Uro positivos.', 'Bil negativo y Uro positivo.', NULL, 'd', NULL, NULL, NULL),
  (2024, 151, 'El Ce4+ se utiliza como reactivo valorante en el análisis cuantitativo de diferentes compuestos en volumetrías de óxido-reducción. ¿Cuál es el indicador apropiado para este tipo de valoraciones?:', 'Murexida.', 'Calmagita.', 'Eritrosina.', 'Ferroína.', NULL, 'd', NULL, NULL, NULL),
  (2024, 152, '¿Con qué aplicación relaciona el uso de los gráficos de Gran?:', 'Con la evaluación de la robustez de un método analítico.', 'Con la evaluación de la exactitud de un método analítico.', 'Con la evaluación de la capacidad amortiguadora de una disolución tampón.', 'Con la evaluación del punto final en una volumetría.', NULL, 'd', NULL, NULL, NULL),
  (2024, 153, '¿Cuál de los siguientes métodos consiste en una valoración de precipitación con detección del punto final mediante un indicador de adsorción?:', 'Método de Mohr.', 'Método de Volhard.', 'Método de Fajans.', 'Método de Kjeldahl.', NULL, 'c', NULL, NULL, NULL),
  (2024, 154, 'A partir de las medidas analíticas obtenidas en una serie de alícuotas o réplicas, ¿cuál de los siguientes parámetros informa sobre la precisión del método analítico?:', 'Pendiente de la recta de calibrado.', 'Error absoluto.', 'Error relativo.', 'Coeficiente de variación.', NULL, 'd', NULL, NULL, NULL),
  (2024, 155, 'El EDTA es un sistema hexaprótico, cuya abreviatura habitual es H6Y2+. Las valoraciones complejométricas con EDTA se realizan a un pH:', 'Ácido, para que predomine la especie H6Y2+, que reacciona con el ion metálico para formar el complejo.', 'Básico, para que predomine la especie H6Y2+, que reacciona con el ion metálico para formar el complejo.', 'Ácido, para que predomine la especie Y4- que reacciona con el ion metálico para formar el complejo.', 'Básico, para que predomine la especie Y4-, que reacciona con el ion metálico para formar el complejo.', NULL, 'd', NULL, NULL, NULL),
  (2024, 156, '¿Cómo se puede aumentar el poder de resolución de un monocromador de red de difracción?:', 'Incrementado la anchura de las rendijas de entrada y de salida.', 'Disminuyendo el número de líneas talladas por milímetro.', 'Incrementando el número de líneas talladas por milímetro.', 'Disminuyendo el orden de difracción en el que se trabaja.', NULL, 'c', NULL, NULL, NULL),
  (2024, 157, 'En espectrometría de emisión atómica con fuente de plasma acoplado inductivamente (ICP), utilizando las mismas condiciones experimentales, se puede realizar el análisis simultáneo de:', 'Elementos alcalino-térreos y gases nobles.', 'Elementos alcalinos y elementos alcalino-térreos.', 'Elementos alcalinos y elementos de transición.', 'Elementos alcalino-térreos y elementos de transición.', NULL, 'd', NULL, NULL, NULL),
  (2024, 158, 'Las fases estacionarias de poliestireno-divinilbenceno (no ionizables) son apropiadas para la siguiente modalidad de cromatografía de líquidos:', 'Cromatografía de intercambio iónico.', 'Cromatografía por exclusión por tamaño.', 'Cromatografía de adsorción.', 'Cromatografía de reparto.', NULL, 'b', NULL, NULL, NULL),
  (2024, 159, 'En el cromatograma que aparece en la figura:', 'Los picos 1 y 3 presentan un factor de selectividad igual a 1 y los picos 5 y 6 una resolución inferior a 1,5.', 'Los picos 1 y 3 presentan un factor de selectividad superior a 1 y los picos 5 y 6 una resolución inferior a 1,5.', 'Los picos 1 y 3 presentan un factor de selectividad igual a 1 y los picos 5 y 6 una resolución superior a 1,5.', 'Los picos 1 y 3 presentan un factor de selectividad superior a 1 y los picos 5 y 6 una resolución superior a 1,5.', NULL, 'a', '/imagenes-fir/2024/159.png', NULL, 'sin_imagen'),
  (2024, 160, 'En la determinación de contaminantes atmosféricos mediante espectrometría de absorción en el infrarrojo, ¿cuál de los siguientes gases presentes en el aire interferiría en su determinación?:', 'O2.', 'N2.', 'CO2.', 'Ar.', NULL, 'c', NULL, NULL, NULL),
  (2024, 161, 'La figura muestra la titulación espectrofotométrica UV-VIS de Cu2+ con EDTA (ácido etilendiaminotetraacético) obtenida al medir el valor de la absorbancia (A) a la longitud de onda de absorción del complejo Cu-EDTA. Se cumple que:', 'El analito (Cu2+) es absorbente a la longitud de onda de trabajo.', 'El titulador (EDTA) es absorbente a la longitud de onda de trabajo.', 'El producto de reacción (Cu-EDTA) es absorbente a la longitud de onda de trabajo.', 'El analito (Cu2+) y el titulador (EDTA) son absorbentes a la longitud de onda de trabajo.', NULL, 'c', '/imagenes-fir/2024/161.png', NULL, 'sin_imagen'),
  (2024, 162, 'Al comparar la adecuación de dos electrodos de membrana de vidrio sensibles a iones hidrógeno, el catión Na+ puede ser una interferencia significativa. Sabiendo que el coeficiente de selectividad potenciométrico para el electrodo A es kH+,Na+ = 10-3 y para el electrodo B es kH+,Na+ = 10-1, se elige:', 'El electrodo A porque el error en las determinaciones será menor al tener menor coeficiente de selectividad potenciométrico.', 'El electrodo A porque el error en las determinaciones será menor al tener mayor coeficiente de selectividad potenciométrico.', 'El electrodo B porque el error en las determinaciones será menor al tener mayor coeficiente de selectividad potenciométrico.', 'El electrodo B porque el error en las determinaciones será menor al tener menor coeficiente de selectividad potenciométrico.', NULL, 'a', NULL, NULL, NULL),
  (2024, 163, 'La corrección de las interferencias espectrales debidas a la matriz de la muestra es útil en:', 'Espectrometría de masas.', 'Espectrometría de absorción atómica.', 'Espectrometría de absorción molecular.', 'Espectrometría Raman.', NULL, 'b', NULL, NULL, NULL),
  (2024, 164, 'El diseño instrumental que se muestra en la figura corresponde a un:', 'Espectrofotómetro de absorción molecular UV visible de haz sencillo.', 'Espectrofotómetro de absorción molecular UV visible de haz doble.', 'Espectrofluorímetro de haz sencillo.', 'Espectrofluorímetro de haz doble.', NULL, 'b', '/imagenes-fir/2024/164.png', NULL, 'sin_imagen'),
  (2024, 165, 'La temperatura óptima de la columna en cromatografía de gases depende del:', 'Punto de ebullición de los analitos y del grado de separación requerido.', 'Punto de fusión de los analitos y del grado de separación requerido.', 'Punto de ebullición de los analitos y del detector utilizado.', 'Punto de fusión de los analitos y del detector utilizado.', NULL, 'a', NULL, NULL, NULL),
  (2024, 166, 'En una cromatografía líquida de partición (reparto) en fase normal, al incrementar la polaridad de la fase móvil:', 'Disminuyen los tiempos de elución ya que la fase estacionaria es más apolar que la fase móvil.', 'Aumentan los tiempos de elución ya que la fase estacionaria es más apolar que la fase móvil.', 'Disminuyen los tiempos de elución ya que la fase estacionaria es más polar que la fase móvil.', 'Aumentan los tiempos de elución ya que la fase estacionaria es más polar que la fase móvil.', NULL, 'c', NULL, NULL, NULL),
  (2024, 167, 'Las disoluciones de una serie de solutos no volátiles con diferentes pesos moleculares tienen una concentración de 1 g de soluto en 1 kg de solvente y se comportan como ideales. ¿Qué efecto tiene el peso molecular del soluto sobre la temperatura de ebullición de las disoluciones resultantes?:', 'A mayor peso molecular, mayor será el incremento de la temperatura de ebullición de la disolución respecto al disolvente puro.', 'A menor peso molecular, mayor será el incremento de la temperatura de ebullición de la disolución respecto al disolvente puro.', 'Como la concentración expresada en g/kg es la misma en todas las disoluciones, no habrá cambios en sus temperaturas de ebullición.', 'El peso molecular del soluto no afecta a la temperatura de ebullición.', NULL, 'b', NULL, NULL, NULL),
  (2024, 168, 'En una reacción de orden 0:', 'La velocidad de la reacción es proporcional a la concentración de reactivos.', 'La representación de la concentración de reactivo frente al tiempo da una línea recta cuya pendiente es proporcional a la constante de velocidad k.', 'El tiempo de semivida es proporcional a k e inversamente proporcional a la concentración inicial de reactivos.', 'En el sistema internacional la constante k tiene unidades de (s-1).', NULL, 'b', NULL, NULL, NULL),
  (2024, 170, '¿Cuáles de los siguientes síntomas son característicos de un toxíndrome (síndrome tóxico) serotoninérgico?:', 'Alteraciones en el grado de conciencia (agitación, confusión…), hiperactividad autonómica y alteraciones neuromusculares.', 'Retención urinaria, estreñimiento y broncoespasmo.', 'Miosis, hipotermia y parálisis.', 'Depresión respiratoria, sudoración excesiva y bradicardia.', NULL, 'a', NULL, NULL, NULL),
  (2024, 171, '¿Cuál de las siguientes intoxicaciones por hongos ocurre solo si se ingiere alcohol de forma simultánea o al cabo de un tiempo de ingerido el hongo, por producirse un efecto disulfiram?:', 'Síndrome hemolítico por Ascomicetos.', 'Síndrome coprínico por Coprinus.', 'Síndrome orellánico por Cortinarius.', 'Síndrome ciclopeptídeo por Amanitas.', NULL, 'b', NULL, NULL, NULL),
  (2024, 173, '¿Para cuál de las siguientes sustancias se recomienda el carbón activado como método de descontaminación digestiva en caso de intoxicación?:', 'Alcoholes (etanol, metanol, etilenglicol).', 'Metales pesados.', 'Fármacos beta-bloqueantes y antagonistas del calcio.', 'Disolventes orgánicos.', NULL, 'c', NULL, NULL, NULL),
  (2024, 174, 'La toxicidad de los antidepresivos tricíclicos se ve potenciada por la interacción con las siguientes sustancias, EXCEPTO una. ¿Cuál es la excepción?:', 'Alcohol.', 'Fármacos anticolinesterásicos.', 'Fármacos antipsicóticos.', 'Fármacos antihistamínicos H1.', NULL, 'b', NULL, NULL, NULL),
  (2024, 175, '¿Cuál es el producto mayoritario que se obtiene al calentar la 2,5-hexanodiona en presencia de hidróxido de sodio en metanol?:', 'El compuesto I.', 'El compuesto II.', 'El compuesto III.', 'El compuesto IV.', NULL, 'c', NULL, NULL, NULL),
  (2024, 176, '¿Cuál o cuáles de los siguientes compuestos presentan quiralidad?:', 'A.', 'A y E.', 'B, C y E.', 'A, C y E.', NULL, 'a', '/imagenes-fir/2024/176.png', NULL, 'sin_imagen'),
  (2024, 177, 'Clasifique las siguientes aminas heterocíclicas (pirrol, pirrolidina, piridina e imidazol) por orden de basicidad creciente:', 'Pirrol < pirrolidina < imidazol < piridina.', 'Piridina < pirrol < pirrolidina < imidazol.', 'Pirrol < piridina < imidazol < pirrolidina.', 'Pirrolidina < pirrol < imidazol < piridina.', NULL, 'c', NULL, NULL, NULL),
  (2024, 178, 'El proceso que se representa es:', 'Una reacción de Diels-Alder.', 'Una anelación de Robinson.', 'Una condensación de Claisen.', 'Una ciclación de Dieckmann.', NULL, 'b', '/imagenes-fir/2024/178.png', NULL, 'sin_imagen'),
  (2024, 179, 'Seleccione de entre las disoluciones acuosas AD que se definen a continuación la que mejor y la que peor conduce la electricidad. A) NH3 0,1 M; B) NaCl 0,1M; C) CH3-CO2H 2M; D) CH3-CH2OH 2M:', 'La mejor, la B y la peor, la D.', 'La mejor, la A y la peor, la B.', 'La mejor, la B y la peor, la C.', 'La mejor, la A y la peor, la D.', NULL, 'a', NULL, NULL, NULL),
