  (2024, 181, '¿Cuál de las siguientes moléculas es una especie apolar?:', 'NO2.', 'SO2.', 'ClF3.', 'BF3.', NULL, 'd', NULL, NULL, NULL),
  (2024, 182, 'En los hospitales se utilizan fuentes radiactivas con fines de diagnóstico y tratamiento. ¿Cuál de las siguientes radiaciones presenta mayor poder de penetración de la materia?:', 'Alfa.', 'Beta.', 'Gamma.', 'El poder de penetración es igual en todas las radiaciones.', NULL, 'c', NULL, NULL, NULL),
  (2024, 183, 'Indique cuál de estos valores es un estadístico de dispersión:', 'Media.', 'Moda.', 'Percentil 50.', 'Rango intercuartílico.', NULL, 'd', NULL, NULL, NULL),
  (2024, 184, 'Indique cuál de las siguientes afirmaciones con respecto a los estudios de casos y controles es INCORRECTA:', 'Son estudios relativamente baratos comparados con otros tipos de estudios.', 'Son estudios observacionales.', 'Resultan adecuados para estudiar exposiciones poco frecuentes.', 'Es recomendable que los controles provengan de la misma población que los casos.', NULL, 'c', NULL, NULL, NULL),
  (2024, 185, 'Indique cuál de los siguientes coeficientes evalúa la reproducibilidad de variables categóricas:', 'Coeficiente kappa.', 'Coeficiente de Bradley-Blackbox.', 'Coeficiente de correlación de Pearson.', 'Coeficiente de correlación de Spearman.', NULL, 'a', NULL, NULL, NULL),
  (2024, 186, 'Para una determinada prueba diagnóstica:', 'La sensibilidad de la prueba aumentará con el aumento de la prevalencia de la enfermedad diagnosticada.', 'La especificidad de la prueba aumentará con el aumento de la prevalencia de la enfermedad diagnosticada.', 'El valor predictivo positivo de la prueba aumentará con el aumento de la prevalencia de la enfermedad diagnosticada.', 'El valor predictivo negativo de la prueba aumentará con el aumento de la prevalencia de la enfermedad diagnosticada.', NULL, 'c', NULL, NULL, NULL),
  (2024, 187, '¿Cuál de las siguientes afirmaciones acerca del sesgo de inclusión es cierta?:', 'Se produce al seleccionar casos con patologías relacionadas con la exposición sujeto de estudio.', 'Se produce al seleccionar casos con patologías no relacionadas con la exposición sujeto de estudio.', 'Se produce al seleccionar controles con patologías relacionadas con la exposición sujeto de estudio.', 'Se produce al seleccionar controles con patologías no relacionadas con la exposición sujeto de estudio.', NULL, 'c', NULL, NULL, NULL),
  (2024, 188, 'Una variable de confusión:', 'Está relacionada tanto con la variable de exposición evaluada como con la variable respuesta.', 'Está relacionada con la variable respuesta, pero no con la variable de exposición evaluada.', 'Es una variable intermedia en la vía etiopatogénica entre la variable de exposición evaluada y la variable respuesta.', 'No produce sesgos en la estimación de la magnitud del efecto de la variable exposición evaluada sobre la variable respuesta.', NULL, 'a', NULL, NULL, NULL),
  (2024, 189, 'Según el Reglamento (UE) 2021/2282 del Parlamento Europeo y del Consejo sobre evaluación de las tecnologías sanitarias, ¿cuál de las siguientes se consideran tecnologías sanitarias?:', 'Medicamentos y productos sanitarios.', 'Productos sanitarios y procedimientos médicos.', 'Medicamentos, productos sanitarios, productos sanitarios para diagnóstico in vitro, procedimientos médicos y medidas para la prevención, diagnóstico o tratamiento de enfermedades.', 'Medicamentos, productos sanitarios, y productos sanitarios para diagnóstico in vitro.', NULL, 'c', NULL, NULL, NULL),
  (2024, 191, '¿En cuál de las siguientes circunstancias se puede solicitar el uso compasivo de un medicamento?:', 'Cuando el medicamento está autorizado en España, pero no registrado.', 'Cuando el medicamento se va a utilizar en una indicación no autorizada en ficha técnica.', 'Cuando el medicamento está en fase de investigación clínica.', 'Cuando el medicamento es de Uso Hospitalario y se va a utilizar en pacientes no ingresados en un hospital.', NULL, 'c', NULL, NULL, NULL),
  (2024, 192, '¿Qué deducción se tiene que aplicar en las compras de medicamentos huérfanos realizadas por los servicios sanitarios del Sistema Nacional Público de Salud?:', '4%.', '5%.', '6,5%.', '7,5%.', NULL, 'a', NULL, NULL, NULL),
  (2024, 193, 'Según la ley de Pareto:', 'El 20% de los medicamentos suponen el 80% del gasto farmacéutico.', 'El 25% de los medicamentos suponen el 75% del gasto farmacéutico.', 'El 30% de los medicamentos suponen el 70% del gasto farmacéutico.', 'El 40% de los medicamentos suponen el 60% del gasto farmacéutico.', NULL, 'a', NULL, NULL, NULL),
  (2024, 194, '¿Cuál de los siguientes mecanismos relacionados con la inmunidad innata es INCORRECTO?:', 'En la respuesta antiviral son clave los Interferones de tipo I.', 'La defensa contra las bacterias fagocitadas e intracelulares está mediada por células NK.', 'Los neutrófilos liberan redes de cromatina llamadas trampas extracelulares del neutrófilo (NET).', 'Los neutrófilos y los macrófagos generan una respuesta conocida como estallido oxidativo.', NULL, 'b', NULL, NULL, NULL),
  (2024, 195, '¿Para qué sirve la prueba de Crossmatch (prueba cruzada) en el trasplante de órganos sólidos?:', 'Para determinar la cantidad de anticuerpos anti-receptor que tiene el donante.', 'Para comprobar si el tipaje para los alelos de los antígenos menores de histocompatibilidad es correcto.', 'Para determinar la presencia de anticuerpos contra el donante que tiene el receptor.', 'Para comprobar que el tipaje para los alelos de los loci DR y DQ es correcto.', NULL, 'c', NULL, NULL, NULL),
  (2024, 196, 'Complete la siguiente frase con la opción más apropiada. La memoria inmunológica ...', 'Es una función esencial de la respuesta inmune y sirve para inhibir respuestas excesivas a antígenos que ya han estado en contacto con el sistema.', 'Depende de la concentración del antígeno que entra en contacto con el sistema inmunitario.', 'Es responsable de la respuesta secundaria y reside en las APC profesionales: macrófagos, células dendríticas y linfocitos B.', 'Es una característica de la respuesta inmune adaptativa que reside en los linfocitos.', NULL, 'd', NULL, NULL, NULL),
  (2024, 197, 'Indique la opción correcta sobre el cambio de isotipo de las inmunoglobulinas:', 'Consiste en el recambio de la región constante de la cadena pesada por una de la cadena ligera.', 'Consiste en el cambio de la región constante de la cadena pesada y ligera de una inmunoglobulina en un mismo linfocito B.', 'Consiste en el cambio de la región constante de la cadena pesada de las inmunoglobulinas expresadas por un linfocito B maduro.', 'Consiste en la adición aleatoria de nucleótidos a las regiones hipervariables de los genes de las inmunoglobulinas.', NULL, 'c', NULL, NULL, NULL),
  (2024, 198, 'Indique qué subpoblación de linfocitos T CD4 efectores se caracteriza por ser abundante en las mucosas, inducir inflamación con reclutamiento de neutrófilos e inducir la producción de péptidos antimicrobianos:', 'TH1, T colaboradores tipo 1.', 'THF, T colaboradores foliculares.', 'TH17, T colaboradores tipo 17.', 'Treg, T reguladores.', NULL, 'c', NULL, NULL, NULL),
  (2024, 199, '¿En cuál de los siguientes síndromes existe ausencia total o parcial de timo, y por ello, el paciente padece un defecto en la producción de linfocitos T?:', 'Síndrome de DiGeorge.', 'Síndrome de la Inmunodeficiencia Adquirida Humana.', 'Síndrome de Bruton.', 'Síndrome de Chédiak-Higashi.', NULL, 'a', NULL, NULL, NULL),
  (2024, 200, 'En algunos pacientes con infección avanzada por el virus de la inmunodeficiencia humana (VIH), el inicio del tratamiento combinado con varios fármacos antirretrovirales, conocido como tratamiento antirretroviral de gran actividad (TARGA), tiene el efecto paradójico de la aparición de un cuadro inflamatorio conocido como:', 'Tormenta de citocinas (o hipercitoquinemia).', 'Síndrome de choque tóxico (TSS).', 'Síndrome inflamatorio de reconstitución inmunitaria (SIRI).', 'Eventos adversos relacionados con el sistema inmunológico (irAEs).', NULL, 'c', NULL, NULL, NULL),
  (2024, 201, 'Un paciente de 35 años presenta dolor abdominal, pancreatitis recurrente y niveles de calcio elevados. En los análisis de laboratorio se observa: Calcio total: 11,8 mg/dL (valores de referencia: 8,5-10,5 mg/dL) PTH: 120 pg/mL (valores de referencia: 10-65 pg/mL) Fósforo: 2,4 mg/dL (valores de referencia: 2,54,5 mg/dL) ¿Cuál es el diagnóstico más probable?:', 'Hiperparatiroidismo subclínico.', 'Hiperparatiroidismo primario.', 'Hiperparatiroidismo secundario a hipercalcemia maligna.', 'Hiperparatiroidismo secundario a insuficiencia renal crónica.', NULL, 'b', NULL, NULL, NULL),
  (2024, 202, '¿En cuál de estas patologías el colágeno NO es la proteína involucrada?:', 'Síndrome de Ehlers-Danlos.', 'Síndrome de Goodpasture.', 'Síndrome de Kearns-Sayre.', 'Osteogénesis imperfecta.', NULL, 'c', NULL, NULL, NULL),
  (2024, 203, 'Un individuo con una lesión en la corteza cerebral muestra no comprender el lenguaje hablado ni tampoco el escrito de palabras o frases, sin embargo, su producción de lenguaje es fluida, pero llena de incorrecciones. ¿Qué zona de la corteza cerebral puede estar dañada?:', 'Corteza parietal superior.', 'Lóbulo occipital.', 'Área de Wernicke.', 'Área de Broca.', NULL, 'c', NULL, NULL, NULL),
  (2024, 204, 'Señale la respuesta correcta en relación con el tratamiento con antifúngicos:', 'La flucitosina se utiliza principalmente asociada a anfotericina B para la meningitis por Aspergillus.', 'Voriconazol presenta menor toxicidad hepática, ocular y cutánea que posaconazol.', 'Anfotericina B presenta un mecanismo de acción fungicida siendo el tratamiento de elección en la mucormicosis invasiva.', 'Las equinocandinas son fungicidas frente a especies de Aspergillus y fungistáticos frente a especies de Candida.', NULL, 'c', NULL, NULL, NULL),
  (2024, 205, 'El dietilestilbestrol es un estrógeno no esteroídico útil en el tratamiento de trastornos menopáusicos y postmenopáusicos. El trans-dietilestilbestrol es 14 veces más activo que el cis-dietilestilbestrol. Estos compuestos son:', 'Enantiómeros.', 'Diastereómeros.', 'Epímeros.', 'Fármacos me-too.', NULL, 'b', NULL, NULL, NULL),
  (2024, 206, 'Mujer de 40 años con artritis psoriásica grave no controlada y sin otros antecedentes clínicos de interés, que ha fracasado al tratamiento con adalimumab. Su trabajo, muy demandante, le exige viajar mucho, además, refiere temor a las agujas. ¿Qué tratamiento podría ofrecérsele a la paciente?:', 'Ruxolitinib.', 'Dupilumab.', 'Upadacitinib.', 'Ponatinib.', NULL, 'c', NULL, NULL, NULL),
  (2024, 207, '¿Cuál de los siguientes está relacionado con el Parvovirus B19?:', 'Linfoma de Burkitt.', 'Enfermedad de Castleman.', 'Eritema infeccioso.', 'Manchas de Koplik.', NULL, 'c', NULL, NULL, NULL),
  (2024, 208, '¿Cuál de los siguientes virus NO forma parte de la familia de los virus herpes?:', 'Virus de Epstein-Barr.', 'Citomegalovirus.', 'Virus de la varicela-zóster.', 'Enterovirus.', NULL, 'd', NULL, NULL, NULL),
  (2024, 209, '¿Cuál de las siguientes estrategias disminuirá la solubilidad en agua de un candidato a fármaco?:', 'La introducción de un grupo hidroxilo.', 'La sustitución de un grupo hidroxilo por un metilo.', 'La reducción de un grupo cetona a alcohol.', 'La oxidación de un grupo aldehído a ácido.', NULL, 'b', NULL, NULL, NULL),
  (2024, 210, 'Indique cuál de estas afirmaciones sobre el modelo de regresión de Cox NO es correcta:', 'También se denomina modelo de regresión de riesgos proporcionales.', 'Es un modelo semiparamétrico que no requiere supuestos sobre la distribución de los tiempos de supervivencia.', 'Los coeficientes estimados en la regresión de Cox se interpretan como logaritmos de razón de riesgos.', 'El modelo asume que las observaciones son independientes entre sí.', NULL, 'd', NULL, NULL, NULL);
